"""Task tools use the versioned .55 reference; never connect to game accounts."""
import json,re
from html import escape as e
from pokebonk_completion import D,requirements,mods_text

def apply_tools(ctx):
 P,pages,article=ctx['P'],ctx['PAGES'],ctx['article']
 old=ctx['DATE'],ctx['VERSION'];ctx['DATE'],ctx['VERSION']='October 28, 2026','v0.8.55 data snapshot'
 flow='<nav class="task-flow" aria-label="Plan a run"><a href="/pokebonk/pokemon/">1 · Find a partner</a><a href="/pokebonk/build-planner/">2 · Draft a build</a><a href="/pokebonk/move-fusions/#finder">3 · Check a fusion</a><a href="/pokebonk/lab/#calculator">4 · Budget the Lab</a></nav>'
 scope='<p class="note">Original pokebonk.com reference: v0.8.55, inspected October 26; tool assembled October 28. This dated dataset is not a live account, performance simulation or current-price guarantee. Our Play window is a separate v0.8.27 edition. Recheck changed cards in your actual game.</p>'
 sources=[(D['source_client'],'pokebonk.com — v0.8.55 original client','SINGLE_SOURCE: public definitions inspected October 26. No full-run, purchase or fusion test.'),(D['source_news'],'pokebonk.com — same-build project notes','Source descriptions; tool recommendations and calculations are editorial processing.')]
 data=json.dumps(D,ensure_ascii=False).replace('</','<\\/')
 payload='<script type="application/json" id="task-data">'+data+'</script>'
 cards=[]
 for x in D['league']:
  kit=', '.join(m['name']+' ('+m['type']+'/'+m['cls']+')'for m in x['kit'])
  req='; '.join(requirements(r)for r in x['requirements']) or 'Inspect the League entry.'
  evo=' → '.join('/'.join(a['names'])+' at '+str(a['level'])for a in x['evolution']) or 'No run evolution in this record.'
  cards.append(f'<details class="partner-card" id="pokemon-{x["id"]}" data-partner="{x["id"]}" data-types="{" ".join(x["types"])}"><summary><img class="partner-portrait" src="/assets/pokebonk/portraits/{x["id"]:03d}.png" width="96" height="96" loading="lazy" alt="{e(x["name"])}"><span class="tag">#{x["id"]:03d} · {e(" / ".join(x["types"]))}</span><strong>{e(x["name"])}</strong><span>{e(x["role"])}</span></summary><p><strong>{e(x["passive"]["name"])}</strong> — {e(mods_text(x["passive"].get("mods",[])))}</p><p>Static fields only; conditional/trigger effects are not fully represented. This is not a strength ranking.</p><p><strong>Kit:</strong> {e(kit)}</p><p><strong>Evolution:</strong> {e(evo)}</p><p><strong>Challenge:</strong> {e(req)}. A finished challenge is separate from capture; check all gates.</p><p><a href="/pokebonk/build-planner/?partner={x["id"]}">Plan this partner</a> · <a href="/pokebonk/unlocks/">Capture requirements</a> · <a href="#pokemon-{x["id"]}">Link to this entry</a></p></details>')
 types=sorted({t for x in D['league']for t in x['types']})
 filters='<div class="tool-controls"><label>Search name, number, role or kit <input type="search" id="partner-search" placeholder="Abra, 63, Psychic…"></label><label>Type <select id="partner-type"><option value="">All types</option>'+''.join(f'<option>{t}</option>'for t in types)+'</select></label><label>Order <select id="partner-sort"><option value="id">Number</option><option value="name">Name</option></select></label><button type="button" id="partner-reset">Reset filters</button></div><p id="partner-count" role="status">79 partners. Expand an entry to inspect it.</p>'
 article('pokemon','PokeBonk Pokemon Finder: 79 Partners, Kits & Unlocks','Find a PokeBonk partner and plan its kit','Search 79 PokeBonk League partners by name, number, type or moves. Inspect kits, evolution and challenges, then carry a partner into the build planner.',
 'Find a League partner below, expand its kit and challenge, then open its build plan. This combines the existing kit, evolution and unlock references without assigning untested power tiers.'+ctx['ref'](1), [('finder','Search the 79 League partners',scope+flow+filters+'<div id="partner-cards" class="partner-grid">'+''.join(cards)+'</div>'),('method','Read the fields before choosing','<p>These are starting-family League records, not all 151 species as selectable partners. A kit lists eligible moves; it does not promise that every move starts equipped or appears in a run. Base stat rankings and full conditional passive evaluations are omitted. No account or unlock state is read.</p>'+ctx['ref'](2))],sources,[('tier-list/','Choose by the role you need'),('evolution/','Inspect evolution details'),('build-planner/','Draft a build')],script='tools.js')
 opts='<option value="">Choose a partner</option>'+''.join(f'<option value="{x["id"]}">{e(x["name"])}</option>'for x in D['league'])
 planner='<noscript><p>The interactive planner needs JavaScript. Use the <a href="/pokebonk/builds/#routes">three written starter routes</a>, <a href="/pokebonk/move-fusions/#recipes">complete fusion table</a> and <a href="/pokebonk/lab/#costs">Lab cost table</a> instead.</p></noscript><form id="build-form"><div id="plan-portrait" hidden><img width="112" height="112" alt=""><p></p></div><label>Partner <select id="plan-partner">'+opts+'</select></label><label>Move capacity <select id="plan-capacity"><option value="3">3 slots</option><option value="4">4 slots — requires Lab upgrade</option></select></label><div id="move-slots" class="tool-controls">'+''.join(f'<label>Move {i+1} <select id="plan-move-{i}"><option value="">Empty</option></select></label>'for i in range(4))+'</div><label>Plan goal <select id="plan-goal"><option value="survival">Survival</option><option value="fusion">Assemble a fusion</option><option value="status">Status challenge</option></select></label><p id="plan-result" role="status">Select a partner to see its eligible kit and slot decisions.</p><div id="plan-pairs"></div><button type="button" id="share-plan">Create share link</button> <button type="reset">Reset plan</button><label>Plan link (copy this address) <input id="plan-link" type="text" readonly></label><p id="share-status" role="status"></p><a id="plan-budget" href="/pokebonk/lab/#calculator">Calculate required Lab purchases →</a></form>'
 article('build-planner','PokeBonk Build Planner: Moves, Fusion & Slot Checks','Plan moves, check pairs and budget the slots','Draft a PokeBonk partner kit with three or four slots, inspect fusion matches, share a reproducible plan and calculate the required Lab purchase costs.',
 'Choose a partner, select its actual listed moves, then check eligible pairs and remaining capacity. A fusion needs both ingredients at level 8 and frees one slot. This tool checks a plan, not DPS, ownership or guaranteed offers.'+ctx['ref'](1), [('planner','Draft a kit before the run',scope+flow+planner),('decisions','Use a goal, then keep a fallback','<p><strong>Survival:</strong> compare move class/type and whether you can keep hitting while moving. Fix the last failure before chasing a late pair. <strong>Fusion:</strong> reserve two ingredient slots; do not assume a fourth move is free. <strong>Status:</strong> read the actual source of the required status; type alone does not establish applications.</p><p>The planner uses the partner’s listed kit. It does not model Mew’s broader pool, later evolution-specific offers, items, archived choices or shared game progress. An unmatched pair uses the fallback rule; a recipe match still requires the actual machine and eligible moves. Share links contain only the version, partner, selected moves, capacity and goal. They do not log in, upload a save or change the game.</p>'+ctx['ref'](2))],sources,[('builds/','Read starter routes and fallback choices'),('items-vitamins/','Match an upgrade to the actual move'),('luck-status-chance/','Choose rarity or status chance')],script='tools.js')
 ctx['DATE'],ctx['VERSION']=old
 def enhance(slug,html):
  page=pages[P+slug+'/'];page['html']=page['html'].replace('<section id=',flow+'<section id=',1)
  page['html']=page['html'].replace('</head>','<link rel="stylesheet" href="/assets/pokebonk/tools.css"></head>')
  if html:page['html']=page['html'].replace('<section id=',html+'<section id=',1)
  if slug in ['pokemon','build-planner','lab']:page['html']=page['html'].replace('</main>',payload+'</main>')
  if slug in ['pokemon','build-planner']:
   page['html']=re.sub(r'<figure>.*?</figure>','',page['html'],flags=re.S)
   page['html']=re.sub(r'<meta property="og:image"[^>]*>','',page['html'])
 for slug in ['pokemon','build-planner','builds','tier-list','move-fusions','items-vitamins']:enhance(slug,'')
 rows=[]
 for x in D['lab']:
  options=''.join(f'<option value="{i}">{i}</option>'for i in range(x['max']+1))
  rows.append(f'<div class="budget-row" data-upgrade="{x["id"]}"><h3>{e(x["name"])}</h3><label>Owned level <select aria-label="Owned {e(x["name"])}">{options}</select></label><label>Target level <select aria-label="Target {e(x["name"])}">{options}</select></label><output>0 Stardust</output></div>')
 budget='<section id="calculator"><noscript><p>JavaScript is needed for automatic totals. The complete cost schedule and worked budgets remain below.</p></noscript><h2>Calculate your own Lab basket</h2><p>v0.8.55 schedule, checked October 26. Choose owned and target levels; only unowned levels count. Hidden rows remain in the total. This is not a purchase or live price check.</p><form id="budget-form"><label>Stardust available <input id="dust" type="number" min="0" max="1000000000" value="0"></label><label>Find an upgrade <input id="budget-search" type="search"></label><p id="budget-total" role="status">Total 0 Stardust · Remaining 0</p><div id="budget-rows">'+''.join(rows)+'</div><button type="reset">Reset budget</button></form><p><a href="/pokebonk/build-planner/">Return to the build planner</a>. Selecting capacity here does not buy or unlock it in the game. Costs exclude item unlocks. A target below owned is raised to owned, never treated as a refund.</p></section>'
 enhance('lab',budget)
 pages[P+'lab/']['html']=pages[P+'lab/']['html'].replace('</head>','<script src="/assets/pokebonk/tools.js" defer></script></head>').replace('<a href="#sources">Sources</a>','<a href="#calculator">Calculate a basket</a><a href="#sources">Sources</a>',1)
 # Put actual route presets next to the existing starter routes, not another ranking.
 for slug, ident, title, text in [
  ('builds','workbench','Turn a route into a checkable plan','<p>Start with a pair, then keep the third slot for the problem you actually face. <a href="/pokebonk/build-planner/?partner=1&amp;goal=fusion&amp;m0=razor-leaf&amp;m1=solar-beam">Bulbasaur: Flower Beam draft</a> · <a href="/pokebonk/build-planner/?partner=4&amp;goal=fusion&amp;m0=fire-spin&amp;m1=flamethrower">Charmander: Fiery Whirlwind draft</a> · <a href="/pokebonk/build-planner/?partner=7&amp;goal=fusion&amp;m0=rapid-spin&amp;m1=hydro-pump">Squirtle: Hydro Spiral draft</a>. Select only moves that are actually available; a draft cannot override locks or Archive.</p><p>With three slots, two ingredients and a useful early attack fill the kit. The planner exposes each possible pair and the slot freed by one fusion. If you need four moves before that point, send the capacity requirement to the Lab calculator. These are alternatives to compare, not a fixed offer order.</p>'),
  ('items-vitamins','plan-scope','Check the scope of each planned upgrade','<p>Put the selected move beside its class and type in the planner. For example, Bulbasaur’s Razor Leaf is Physical and Solar Beam is Special; a Physical-only bonus does not cover both. Squirtle’s Rapid Spin is Normal and Hydro Pump is Water; Water-only damage does not cover the entire pre-fusion pair. Use the completed fusion’s part descriptions before choosing Area, Duration or Projectiles.</p><p>For conditional sources, keep the activation condition in the plan: a low-HP bonus requires low HP, and a status bonus still needs an actual applying hit. The static table is not a complete trigger simulation. Do not add every displayed percentage into one supposed DPS total. <a href="/pokebonk/build-planner/">Inspect the actual move kit</a> and <a href="/pokebonk/luck-status-chance/">compare status and rarity examples</a>.</p>')]:
  page=pages[P+slug+'/'];page['html']=page['html'].replace('<section class="sources"',f'<section id="{ident}"><h2>{title}</h2>{text}</section><section class="sources"',1).replace('<a href="#sources">Sources</a>',f'<a href="#{ident}">{title}</a><a href="#sources">Sources</a>',1)
 for slug in ['pokemon','build-planner']:
  card=f'<a href="{P+slug}/">'+('Partner finder<span>79 kits, evolution and capture gates' if slug=='pokemon' else 'Build planner<span>Choose moves, check slots and share a plan')+'</span></a>'
  marker='<h3>Builds & choices</h3><div class="guide-index">';pages[P]['html']=pages[P]['html'].replace(marker,marker+card,1)
 # Add the workflow near the home guide index, preserving existing hero and nav.
 pages[P]['html']=pages[P]['html'].replace('<div class="guide-index">',flow+'<div class="guide-index">',1).replace('</head>','<link rel="stylesheet" href="/assets/pokebonk/tools.css"></head>')
 # Reuse the same identification portraits; leave all role recommendations unchanged.
 for x in D['league']:
  page=pages[P+'tier-list/'];needle='<td>'+e(x['name'])+'</td>'
  image=f'<img class="table-portrait" src="/assets/pokebonk/portraits/{x["id"]:03d}.png" width="56" height="56" loading="lazy" alt="">'
  page['html']=page['html'].replace(needle,'<td>'+image+e(x['name'])+'</td>')
 notice='<section class="portrait-credit" id="portrait-credits"><h2>Pokémon image credits</h2><p>Pokémon character images and associated names belong to their respective rights holders, including Nintendo, Creatures Inc. and GAME FREAK Inc. Local copies were sourced from <a href="https://pokemon-team-builder.org/tools/pokebonk-tier-list" target="_blank" rel="noopener noreferrer">Pokemon Team Builder ↗</a>. We use these images for identification and commentary under our assertion of fair use. This is not a claim of official permission, affiliation or endorsement. For rights concerns, use our <a href="/pokebonk/contact/">contact page</a>.</p></section>'
 for slug in ['pokemon','build-planner','tier-list']:
  pages[P+slug+'/']['html']=pages[P+slug+'/']['html'].replace('<section class="related">',notice+'<section class="related">',1)
 return flow
